"""Engine-neutral contract for DTMF collection in the voice layer."""

from __future__ import annotations

from typing import Awaitable, Callable, Optional

from pydantic import BaseModel, ConfigDict


class ActiveDTMFCollect(BaseModel):
    """Describe the active engine collect that accepts DTMF input."""

    model_config = ConfigDict(frozen=True)

    field_name: str
    length: Optional[int]
    finish_on_key: Optional[str]
    allow_audio_input: bool


ActiveDTMFCollectResolver = Callable[[str], Awaitable[Optional[ActiveDTMFCollect]]]
